{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cogs_otb_v2 as WITH default_inwards_cogs AS ( select TO_DATE(month, \'DD-MM-YYYY\') AS month, l_1 l1,cat,default_inwards_cogs from snitch_db.maplemonk.inwards_plan_default_sheet1 ) , meta_sku_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, MAX(COALESCE(a.cogs, 0)) AS sku_cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), l1cat_avg_cogs AS ( SELECT l1_category, category, AVG(NULLIF(sku_cogs, 0)) AS avg_cogs FROM meta_sku_map GROUP BY 1, 2 ), sales_pred_qty AS ( WITH actual_targets AS ( SELECT category, l_1_category AS l1_category, DATE_TRUNC(\'MONTH\', TO_DATE(month, \'DD/MM/YYYY\')) AS month, SUM(COALESCE(qty, 0)) AS qty FROM snitch_db.maplemonk.sales_pred_channel_targets_set GROUP BY 1, 2, 3 ), actual_months AS ( SELECT DISTINCT month FROM actual_targets ), future_targets_unpivot AS ( SELECT l_1 AS l1_category, cat AS category, month_name, qty FROM snitch_db.maplemonk.sales_pred_demand_pred UNPIVOT ( qty FOR month_name IN ( MAY, JUNE, JULY, AUG, SEPT, OCT, NOV, DEC, JAN, FEB ) ) ), future_targets AS ( SELECT category, l1_category, CASE UPPER(month_name) WHEN \'MAY\' THEN DATE \'2026-05-01\' WHEN \'JUNE\' THEN DATE \'2026-06-01\' WHEN \'JULY\' THEN DATE \'2026-07-01\' WHEN \'AUG\' THEN DATE \'2026-08-01\' WHEN \'SEPT\' THEN DATE \'2026-09-01\' WHEN \'OCT\' THEN DATE \'2026-10-01\' WHEN \'NOV\' THEN DATE \'2026-11-01\' WHEN \'DEC\' THEN DATE \'2026-12-01\' WHEN \'JAN\' THEN DATE \'2027-01-01\' WHEN \'FEB\' THEN DATE \'2027-02-01\' END AS month, SUM(COALESCE(qty, 0)) AS qty FROM future_targets_unpivot GROUP BY 1, 2, 3 ), future_targets_filtered AS ( SELECT f.* FROM future_targets f LEFT JOIN actual_months a ON f.month = a.month WHERE a.month IS NULL ) SELECT category, l1_category, month, qty FROM actual_targets UNION ALL SELECT category, l1_category, month, qty FROM future_targets_filtered ), sales_pred_cogs AS ( SELECT s.month, s.l1_category AS l1, s.category AS cat, SUM(COALESCE(s.qty, 0) * COALESCE(a.avg_cogs, 0)) AS sales_pred_cogs FROM sales_pred_qty s LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(s.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(s.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), inwards_qty AS ( WITH base AS ( SELECT final_sku AS sku, COALESCE(qty, 0) AS qty, UPPER( REGEXP_SUBSTR( remarks_final, \'March|April|May|June|July|August|September|October|November|December|January|February\', 1, 1, \'i\' ) ) AS month_name FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks WHERE final_sku IS NOT NULL ), non_march AS ( SELECT sku, CASE WHEN month_name = \'APRIL\' THEN DATE \'2026-04-01\' WHEN month_name = \'MAY\' THEN DATE \'2026-05-01\' WHEN month_name = \'JUNE\' THEN DATE \'2026-06-01\' WHEN month_name = \'JULY\' THEN DATE \'2026-07-01\' WHEN month_name = \'AUGUST\' THEN DATE \'2026-08-01\' WHEN month_name = \'SEPTEMBER\' THEN DATE \'2026-09-01\' WHEN month_name = \'OCTOBER\' THEN DATE \'2026-10-01\' WHEN month_name = \'NOVEMBER\' THEN DATE \'2026-11-01\' WHEN month_name = \'DECEMBER\' THEN DATE \'2026-12-01\' WHEN month_name = \'JANUARY\' THEN DATE \'2027-01-01\' WHEN month_name = \'FEBRUARY\' THEN DATE \'2027-02-01\' END AS month, qty FROM base WHERE month_name IS NOT NULL AND month_name <> \'MARCH\' ), march_data AS ( SELECT sku, DATE \'2026-03-01\' AS month, COALESCE(qty, 0) AS qty FROM snitch_db.maplemonk.march_only_inwards_list_mar_only_inwards_list___qty ) SELECT sku, month, qty FROM non_march UNION ALL SELECT sku, month, qty FROM march_data ), inwards_cogs AS ( SELECT i.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(i.qty, 0) * COALESCE( NULLIF(m.sku_cogs, 0), a.avg_cogs, 0 ) ) AS inwards_target_cogs FROM inwards_qty i LEFT JOIN meta_sku_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 1) ) ) LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), inwards_plan_presence AS ( SELECT i.month, m.l1_category AS l1, m.category AS cat, COUNT(*) AS plan_row_count FROM inwards_qty i LEFT JOIN meta_sku_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(i.sku, \' \', \'\'), \'-\', 1) ) ) GROUP BY 1, 2, 3 ), actual_inwards_qty AS ( SELECT DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE) AS month, UPPER( IFF( UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= DATE \'2026-03-01\' AND LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2 HAVING SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) >= 30 ), actual_inwards_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS actual_inwards_cogs FROM actual_inwards_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), return_inwards_qty AS ( SELECT DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE) AS month, UPPER( IFF( UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, CASE WHEN UPPER(TRIM(FINAL_TYPE)) = \'STORE RETURN INWARD\' THEN \'STORE_RETURN_INWARDS\' WHEN UPPER(TRIM(FINAL_TYPE)) = \'B2C RETURN INWARD\' THEN \'B2C_RETURN_INWARDS\' END AS return_type, SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= DATE \'2026-03-01\' AND UPPER(TRIM(FINAL_TYPE)) IN (\'STORE RETURN INWARD\', \'B2C RETURN INWARD\') GROUP BY 1, 2, 3 ), return_inwards_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( CASE WHEN q.return_type = \'STORE_RETURN_INWARDS\' THEN COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ELSE 0 END ) AS store_return_inwards_cogs, SUM( CASE WHEN q.return_type = \'B2C_RETURN_INWARDS\' THEN COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ELSE 0 END ) AS b2c_return_inwards_cogs, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS return_inwards_cogs FROM return_inwards_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), actual_sales_qty AS ( SELECT DATE_TRUNC(\'MONTH\', date::DATE) AS month, UPPER( IFF( UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, SUM(COALESCE(gross_quantity::INT, 0)) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date::DATE >= DATE \'2026-03-01\' GROUP BY 1, 2 ), actual_sales_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS actual_sales_cogs FROM actual_sales_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), last_30d_sales_qty AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sku_group, SUM(COALESCE(gross_quantity::INT, 0)) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date::DATE >= CURRENT_DATE - 30 AND date::DATE < CURRENT_DATE GROUP BY 1,2 ), last_30d_sales_cogs AS ( SELECT sku_group, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS last_30d_sales_cogs, SUM( COALESCE(q.qty, 0)) qty FROM last_30d_sales_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2,3 ), inventory_now_cogs_raw AS ( SELECT DATE::DATE AS snapshot_date, UPPER( IFF( UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE(AVAILABLE_COGS, 0) + COALESCE(BLOCKED_COGS, 0) + COALESCE(NOT_FOUND_COGS, 0) + COALESCE(BAD_INVENTORY_COGS, 0) + COALESCE(NOT_SYNCED_COGS, 0) + COALESCE(PUTAWAY_PENDING_COGS, 0) + COALESCE(PUTBACK_PENDING_COGS, 0) + COALESCE(STOCK_TRANSFER_COGS, 0) + COALESCE(OFFLINE_AVAILABLE_COGS, 0) + COALESCE(JIT_COGS, 0) AS current_inventory_cogs FROM snitch_db.maplemonk.cogs_daily_snapshot WHERE DATE::DATE = ( SELECT MAX(DATE::DATE) FROM snitch_db.maplemonk.cogs_daily_snapshot ) ), inventory_now_cogs AS ( SELECT r.snapshot_date, m.l1_category AS l1, m.category AS cat, SUM(COALESCE(r.current_inventory_cogs, 0)) AS current_inventory_cogs FROM inventory_now_cogs_raw r LEFT JOIN meta_sku_map m ON r.sku_group_clean = m.sku_group_clean GROUP BY 1, 2, 3 ), monthly_metrics_cogs AS ( SELECT COALESCE(s.month, i.month, a.month, r.month, sl.month) AS month, COALESCE(s.l1, i.l1, a.l1, r.l1, sl.l1) AS l1, COALESCE(s.cat, i.cat, a.cat, r.cat, sl.cat) AS cat, COALESCE(s.sales_pred_cogs, 0) AS sales_pred_cogs, COALESCE(i.inwards_target_cogs, 0) AS inwards_target_cogs, COALESCE(a.actual_inwards_cogs, 0) AS actual_inwards_cogs, COALESCE(r.store_return_inwards_cogs, 0) AS store_return_inwards_cogs, COALESCE(r.b2c_return_inwards_cogs, 0) AS b2c_return_inwards_cogs, COALESCE(r.return_inwards_cogs, 0) AS return_inwards_cogs, COALESCE(sl.actual_sales_cogs, 0) AS actual_sales_cogs FROM sales_pred_cogs s FULL OUTER JOIN inwards_cogs i ON s.month = i.month AND UPPER(TRIM(s.l1)) = UPPER(TRIM(i.l1)) AND UPPER(TRIM(s.cat)) = UPPER(TRIM(i.cat)) FULL OUTER JOIN actual_inwards_cogs a ON COALESCE(s.month, i.month) = a.month AND UPPER(TRIM(COALESCE(s.l1, i.l1))) = UPPER(TRIM(a.l1)) AND UPPER(TRIM(COALESCE(s.cat, i.cat))) = UPPER(TRIM(a.cat)) FULL OUTER JOIN return_inwards_cogs r ON COALESCE(s.month, i.month, a.month) = r.month AND UPPER(TRIM(COALESCE(s.l1, i.l1, a.l1))) = UPPER(TRIM(r.l1)) AND UPPER(TRIM(COALESCE(s.cat, i.cat, a.cat))) = UPPER(TRIM(r.cat)) FULL OUTER JOIN actual_sales_cogs sl ON COALESCE(s.month, i.month, a.month, r.month) = sl.month AND UPPER(TRIM(COALESCE(s.l1, i.l1, a.l1, r.l1))) = UPPER(TRIM(sl.l1)) AND UPPER(TRIM(COALESCE(s.cat, i.cat, a.cat, r.cat))) = UPPER(TRIM(sl.cat)) ), anchor_info AS ( SELECT DATE_TRUNC(\'MONTH\', MAX(snapshot_date)) AS anchor_month, CASE WHEN MONTH(MAX(snapshot_date)) IN (1, 2) THEN DATE_FROM_PARTS(YEAR(MAX(snapshot_date)) - 1, 3, 1) ELSE DATE_FROM_PARTS(YEAR(MAX(snapshot_date)), 3, 1) END AS fiscal_start_month FROM inventory_now_cogs ), months AS ( SELECT DATEADD(MONTH, seq4(), a.fiscal_start_month) AS month FROM anchor_info a, TABLE(GENERATOR(ROWCOUNT => 12)) ), keys AS ( SELECT DISTINCT l1, cat FROM monthly_metrics_cogs WHERE l1 IS NOT NULL AND cat IS NOT NULL UNION SELECT DISTINCT l1, cat FROM inventory_now_cogs WHERE l1 IS NOT NULL AND cat IS NOT NULL UNION SELECT DISTINCT l1, cat FROM default_inwards_cogs ), grid AS ( SELECT m.month, k.l1, k.cat FROM months m CROSS JOIN keys k ), base_filled AS ( SELECT g.month, g.l1, g.cat, COALESCE(mm.sales_pred_cogs, 0) AS sales_pred_cogs, CASE WHEN COALESCE(p.plan_row_count, 0) = 0 THEN COALESCE(d.default_inwards_cogs, 0) ELSE COALESCE(mm.inwards_target_cogs, 0) END AS inwards_target_cogs, COALESCE(mm.actual_inwards_cogs, 0) AS actual_inwards_cogs, COALESCE(mm.store_return_inwards_cogs, 0) AS store_return_inwards_cogs, COALESCE(mm.b2c_return_inwards_cogs, 0) AS b2c_return_inwards_cogs, COALESCE(mm.return_inwards_cogs, 0) AS return_inwards_cogs, COALESCE(mm.actual_sales_cogs, 0) AS actual_sales_cogs, COALESCE(l30.last_30d_sales_cogs, 0) AS last_30d_sales_cogs, COALESCE(inv.current_inventory_cogs, 0) AS current_inventory_cogs FROM grid g LEFT JOIN monthly_metrics_cogs mm ON g.month = mm.month AND UPPER(TRIM(g.l1)) = UPPER(TRIM(mm.l1)) AND UPPER(TRIM(g.cat)) = UPPER(TRIM(mm.cat)) LEFT JOIN inventory_now_cogs inv ON UPPER(TRIM(g.l1)) = UPPER(TRIM(inv.l1)) AND UPPER(TRIM(g.cat)) = UPPER(TRIM(inv.cat)) LEFT JOIN inwards_plan_presence p ON g.month = p.month AND UPPER(TRIM(g.l1)) = UPPER(TRIM(p.l1)) AND UPPER(TRIM(g.cat)) = UPPER(TRIM(p.cat)) LEFT JOIN default_inwards_cogs d ON g.month = d.month AND UPPER(TRIM(g.l1)) = UPPER(TRIM(d.l1)) AND UPPER(TRIM(g.cat)) = UPPER(TRIM(d.cat)) LEFT JOIN last_30d_sales_cogs l30 ON UPPER(TRIM(g.l1)) = UPPER(TRIM(l30.l1)) AND UPPER(TRIM(g.cat)) = UPPER(TRIM(l30.cat)) ), calc_base AS ( SELECT b.*, ai.anchor_month, ai.fiscal_start_month, DATEDIFF(MONTH, ai.fiscal_start_month, b.month) AS month_idx, DATEDIFF(MONTH, ai.fiscal_start_month, ai.anchor_month) AS anchor_idx, COALESCE(b.actual_sales_cogs, 0) - COALESCE(b.actual_inwards_cogs, 0) - COALESCE(b.b2c_return_inwards_cogs, 0) AS actual_backflow_cogs, CASE WHEN DATE_TRUNC(\'MONTH\', b.month) < DATE_TRUNC(\'MONTH\', CURRENT_DATE) THEN 0 ELSE COALESCE(b.sales_pred_cogs, 0) - COALESCE(b.actual_sales_cogs, 0) END AS sales_pred_left_cogs, case WHEN DATE_TRUNC(\'MONTH\', b.month) < DATE_TRUNC(\'MONTH\', CURRENT_DATE) THEN 0 ELSE COALESCE(b.inwards_target_cogs, 0) - COALESCE(b.actual_inwards_cogs, 0) end AS inwards_left_cogs, - COALESCE(b.sales_pred_cogs, 0) - COALESCE(b.actual_sales_cogs, 0) + COALESCE(b.inwards_target_cogs, 0) - COALESCE(b.actual_inwards_cogs, 0) AS future_net_cogs FROM base_filled b CROSS JOIN anchor_info ai ), calc_windows AS ( SELECT c.*, SUM(COALESCE(actual_backflow_cogs, 0)) OVER ( PARTITION BY l1, cat ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_actual_backflow_cogs, SUM(COALESCE(future_net_cogs, 0)) OVER ( PARTITION BY l1, cat ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_future_net_cogs, SUM(COALESCE(future_net_cogs, 0)) OVER ( PARTITION BY l1, cat ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_future_net_prev_cogs FROM calc_base c ), calc_anchor AS ( SELECT w.*, MAX(CASE WHEN month_idx = anchor_idx THEN cum_actual_backflow_cogs END) OVER ( PARTITION BY l1, cat ) AS anchor_cum_actual_backflow_cogs, MAX(CASE WHEN month_idx = anchor_idx THEN cum_future_net_cogs END) OVER ( PARTITION BY l1, cat ) AS anchor_cum_future_net_cogs, MAX(CASE WHEN month_idx = anchor_idx THEN cum_future_net_prev_cogs END) OVER ( PARTITION BY l1, cat ) AS anchor_cum_future_net_prev_cogs FROM calc_windows w ), final_output AS ( SELECT month, l1, cat, sales_pred_cogs, inwards_target_cogs, actual_inwards_cogs, store_return_inwards_cogs, b2c_return_inwards_cogs, return_inwards_cogs, actual_sales_cogs, last_30d_sales_cogs, CASE WHEN month = anchor_month THEN current_inventory_cogs ELSE NULL END AS current_inventory_cogs_anchor_month, sales_pred_left_cogs, inwards_left_cogs, CASE WHEN month_idx < anchor_idx THEN COALESCE(current_inventory_cogs, 0) + COALESCE(anchor_cum_actual_backflow_cogs, 0) - COALESCE(cum_actual_backflow_cogs, 0) + COALESCE(actual_backflow_cogs, 0) WHEN month_idx = anchor_idx THEN COALESCE(current_inventory_cogs, 0) + COALESCE(actual_backflow_cogs, 0) WHEN month_idx > anchor_idx THEN COALESCE(current_inventory_cogs, 0) + COALESCE(cum_future_net_prev_cogs, 0) - COALESCE(anchor_cum_future_net_prev_cogs, 0) ELSE 0 END AS opening_cogs, CASE WHEN month_idx < anchor_idx THEN COALESCE(current_inventory_cogs, 0) + COALESCE(anchor_cum_actual_backflow_cogs, 0) - COALESCE(cum_actual_backflow_cogs, 0) WHEN month_idx = anchor_idx THEN COALESCE(current_inventory_cogs, 0) - COALESCE(sales_pred_left_cogs, 0) + COALESCE(inwards_left_cogs, 0) WHEN month_idx > anchor_idx THEN COALESCE(current_inventory_cogs, 0) + COALESCE(cum_future_net_cogs, 0) - COALESCE(anchor_cum_future_net_prev_cogs, 0) ELSE 0 END AS closing_cogs FROM calc_anchor ) SELECT month, l1, cat, round(sales_pred_cogs/10000000,2) sales_pred_cogs, round(inwards_target_cogs/10000000,2) inwards_target_cogs, round(actual_inwards_cogs/10000000,2) actual_inwards_cogs, round(store_return_inwards_cogs/10000000,2) store_return_inwards_cogs, round(b2c_return_inwards_cogs/10000000,2)b2c_return_inwards_cogs, round(return_inwards_cogs/10000000,2)return_inwards_cogs, round(actual_sales_cogs/10000000,2)actual_sales_cogs, round(current_inventory_cogs_anchor_month/10000000,2)current_inventory_cogs_anchor_month, round(sales_pred_left_cogs/10000000,2)sales_pred_left_cogs, round(inwards_left_cogs/10000000,2)inwards_left_cogs, round(opening_cogs/10000000,2)opening_cogs, round(closing_cogs/10000000,2)closing_cogs, round(last_30d_sales_cogs/10000000,2)last_30d_sales_cogs, round((COALESCE(inwards_target_cogs, 0) - COALESCE(actual_inwards_cogs, 0))/10000000,2) AS mom_inwards_difference_cogs FROM final_output ORDER BY month, l1, cat;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
